      const hmPrn = [0.6, 3.8, orEnd1 + 0.7, orEnd1 + 3.5, orEnd1 + 7, orEnd1 + 12, orEnd1 + 17, orEnd2 + 1, orEnd2 + 6, orEnd2 + 12, orEnd3 + 1.5, orEnd3 + 8, stepH + 3, stepH + 14, stepH + 26];
